export function AssistantPage() {
  const { user, notify, aiConfig } = useApp()
  const [messages, setMessages] = useState([{ from: 'ai', text: `Olá, ${user?.name?.split(' ')[0] || 'por aqui'}! Sou o Assistente IA do Centro Educa Mais. Como posso apoiar sua próxima decisão?` }])
  const [input, setInput] = useState('')
  const [typing, setTyping] = useState(false)
  const suggestions = user?.role === 'PROFESSOR' ? ['Crie uma atividade de Matemática para a turma 100', 'Planeje uma aula sobre funções', 'Monte uma rubrica de avaliação'] : user?.role === 'GESTOR_PEDAGOGICO' ? ['Quais alunos estão com baixo desempenho?', 'Analise esta turma', 'Sugira uma intervenção'] : ['Quais atividades estão pendentes?', 'Como posso melhorar a média?', 'Monte um plano de estudos']
  const send = async (text = input) => { if (!text.trim()) return; const prompt = text.trim(); setMessages((current) => [...current, { from: 'user', text: prompt }]); setInput(''); setTyping(true); try { const answer = await requestAI(aiConfig, prompt, faqResponses); setMessages((current) => [...current, { from: 'ai', text: answer }]) } catch (error) { setMessages((current) => [...current, { from: 'ai', text: 'Não consegui consultar o provedor configurado. Confira a chave, o modelo e a conexão.' }]); notify({ title: 'Falha na IA', message: error instanceof Error ? error.message : 'Revise a configuração do provedor.', tone: 'warning' }) } finally { setTyping(false) } }
  return <div><PageHeader eyebrow="Inteligência institucional" title="Assistente IA" description={user?.role === 'PROFESSOR' ? 'Crie atividades, planeje aulas e monte avaliações com apoio da IA — sempre com revisão docente.' : 'Um espaço de orientação para transformar dados escolares em próximos passos — sempre com decisão humana.'} action={<Badge tone="success"><Sparkles size={13} className="mr-1" /> Mock ativo</Badge>} /><AIProviderCard /><Card className="mx-auto flex min-h-[560px] max-w-5xl flex-col overflow-hidden"><div className="flex items-center gap-3 border-b border-line/70 bg-cream/60 p-4 dark:border-white/10 dark:bg-white/5"><div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-navy text-white"><Bot size={22} /></div><div><h2 className="font-bold text-ink dark:text-white">Assistente IA — Domingos Vieira Filho</h2><p className="text-xs text-slate-500 dark:text-slate-400">Contexto: {user?.description || 'gestão escolar'} · respostas demonstrativas</p></div><button onClick={() => setMessages([])} className="ml-auto rounded-xl p-2.5 text-slate-400 hover:bg-white hover:text-rose-500 dark:hover:bg-white/10" aria-label="Limpar conversa"><RotateCcw size={17} /></button></div><div className="flex-1 space-y-4 overflow-y-auto p-5 sm:p-8">{messages.map((message, index) => <div key={`${message.from}-${index}`} className={`flex gap-3 ${message.from === 'user' ? 'justify-end' : ''}`}><div className={`max-w-[78%] rounded-2xl px-4 py-3 text-sm leading-6 ${message.from === 'user' ? 'rounded-br-md bg-navy text-white' : 'rounded-bl-md bg-cream text-slate-700 dark:bg-white/8 dark:text-slate-200'}`}>{message.text}</div></div>)}{typing && <div className="flex items-center gap-2 text-xs text-slate-400"><span className="h-2 w-2 animate-pulse rounded-full bg-teal" /><span>IA está digitando...</span></div>}{messages.length <= 1 && <div className="pt-3"><p className="mb-3 text-xs font-bold uppercase tracking-wider text-slate-400">Sugestões rápidas</p><div className="flex flex-wrap gap-2">{suggestions.map((suggestion) => <button key={suggestion} onClick={() => send(suggestion)} className="rounded-full border border-line bg-white px-3 py-2 text-xs font-semibold text-slate-500 hover:border-teal hover:text-teal dark:border-white/10 dark:bg-white/5 dark:text-slate-300">{suggestion}</button>)}</div></div>}</div><form onSubmit={(event) => { event.preventDefault(); send() }} className="border-t border-line/70 p-4 dark:border-white/10"><div className="flex items-end gap-3 rounded-2xl border border-line bg-white p-2 focus-within:border-teal dark:border-white/10 dark:bg-white/5"><textarea value={input} onChange={(event) => setInput(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter' && !event.shiftKey) { event.preventDefault(); send() } }} rows={1} aria-label="Mensagem para o assistente" placeholder={user?.role === 'PROFESSOR' ? 'Peça uma atividade, plano de aula ou rubrica...' : 'Escreva uma pergunta sobre a escola...'} className="max-h-24 min-h-10 flex-1 resize-none bg-transparent px-2 py-2 text-sm outline-none dark:text-white" /><button type="submit" className="flex h-10 w-10 items-center justify-center rounded-xl bg-navy text-white transition hover:bg-[#0f314b]" aria-label="Enviar mensagem"><Send size={17} /></button></div><p className="mt-2 px-2 text-[10px] text-slate-400">A IA é uma interface de apoio e não substitui decisões humanas sobre estudantes, professores ou avaliações.</p></form></Card></div>
}

function AIProviderCard() {
  const { aiConfig, setAIConfig, notify } = useApp()
  const [provider, setProvider] = useState(aiConfig.provider)
  const [apiKey, setApiKey] = useState(aiConfig.apiKey)
  const [model, setModel] = useState(aiConfig.model)
  const [testing, setTesting] = useState(false)
  useEffect(() => { setProvider(aiConfig.provider); setApiKey(aiConfig.apiKey); setModel(aiConfig.model) }, [aiConfig.provider, aiConfig.apiKey, aiConfig.model])
  const save = (event: React.FormEvent) => { event.preventDefault(); setAIConfig({ provider, apiKey, model }); notify({ title: 'Provedor salvo', message: provider === 'mock' ? 'O assistente continuará usando respostas demonstrativas.' : 'A configuração foi salva somente nesta sessão para este usuário.', tone: 'success' }) }
  const testConnection = async () => { if (provider === 'mock') { notify({ title: 'Modo demonstração ativo', message: 'Troque para Gemini ou OpenAI para testar uma chave real.', tone: 'info' }); return }; if (!apiKey.trim()) { notify({ title: 'Chave ausente', message: `Cole uma chave válida do ${provider === 'gemini' ? 'Google AI Studio' : 'OpenAI'}.`, tone: 'warning' }); return }; setTesting(true); try { const answer = await requestAI({ provider, apiKey: apiKey.trim(), model }, 'Responda apenas: conexão funcionando.', ['conexão funcionando']); notify({ title: 'Conexão funcionando', message: answer.slice(0, 120), tone: 'success' }) } catch (error) { notify({ title: 'Falha na conexão', message: error instanceof Error ? error.message : 'Verifique a chave e o modelo.', tone: 'warning' }) } finally { setTesting(false) } }
  return <Card className="mx-auto mb-5 max-w-5xl border-teal/20 bg-teal/5 p-5 dark:bg-teal/10"><div className="mb-4 flex items-start justify-between gap-3"><div><p className="text-sm font-bold text-ink dark:text-white">Configurar provedor de IA</p><p className="mt-1 text-xs leading-5 text-slate-500 dark:text-slate-300">Use uma chave própria do Gemini ou OpenAI. A chave fica somente na sessão deste usuário; para produção, mova a chamada para o backend.</p></div><Badge tone={aiConfig.provider === 'mock' ? 'neutral' : 'success'}>{aiConfig.provider === 'mock' ? 'Mock ativo' : aiConfig.provider === 'openai' ? 'OpenAI ativo' : 'Gemini ativo'}</Badge></div><form onSubmit={save} className="grid gap-3 md:grid-cols-[170px_1fr_180px_auto]"><select value={provider} onChange={(event) => setProvider(event.target.value as typeof provider)} className="rounded-xl border border-line bg-white px-3 py-2.5 text-xs font-bold dark:border-white/10 dark:bg-white/5 dark:text-white"><option value="mock">Demonstração</option><option value="openai">OpenAI</option><option value="gemini">Gemini</option></select><input type="password" value={apiKey} onChange={(event) => setApiKey(event.target.value)} placeholder={provider === 'gemini' ? 'Chave Gemini AI Studio' : provider === 'openai' ? 'Chave OpenAI' : 'Sem chave no modo demonstração'} disabled={provider === 'mock'} className="rounded-xl border border-line bg-white px-3 py-2.5 text-xs outline-none focus:border-teal disabled:opacity-60 dark:border-white/10 dark:bg-white/5 dark:text-white" /><input value={model} onChange={(event) => setModel(event.target.value)} placeholder={provider === 'gemini' ? 'gemini-2.5-flash' : 'gpt-4o-mini'} disabled={provider === 'mock'} className="rounded-xl border border-line bg-white px-3 py-2.5 text-xs outline-none focus:border-teal disabled:opacity-60 dark:border-white/10 dark:bg-white/5 dark:text-white" /><Button type="submit" size="sm"><Save size={14} /> Salvar</Button></form><Button type="button" variant="secondary" size="sm" className="mt-3" onClick={testConnection} disabled={testing}>{testing ? 'Testando...' : 'Testar conexão'}</Button><p className="mt-3 text-[10px] leading-4 text-slate-400">Modelo Gemini recomendado: <strong>gemini-2.5-flash</strong>. Não inclua a chave em capturas ou mensagens.</p></Card>
}

async function requestAI(config: { provider: 'mock' | 'openai' | 'gemini'; apiKey: string; model: string }, prompt: string, fallback: string[]) {
  if (config.provider === 'mock' || !config.apiKey) return new Promise<string>((resolve) => window.setTimeout(() => resolve(fallback[Math.floor(Math.random() * fallback.length)]), 700))
  if (config.provider === 'openai') { const response = await fetch('https://api.openai.com/v1/chat/completions', { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${config.apiKey}` }, body: JSON.stringify({ model: config.model || 'gpt-4o-mini', messages: [{ role: 'system', content: 'Você é um assistente pedagógico do Centro Educa Mais Domingos Vieira Filho. Responda em português do Brasil, seja prático e preserve a privacidade dos estudantes.' }, { role: 'user', content: prompt }] }) }); if (!response.ok) { const detail = await response.text(); throw new Error(`OpenAI ${response.status}: ${readProviderError(detail)}`) }; const data = await response.json() as { choices?: Array<{ message?: { content?: string } }> }; return data.choices?.[0]?.message?.content || 'A OpenAI não retornou texto.' }
  const model = (config.model || 'gemini-2.5-flash').replace(/^models\//, '').trim()
  const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent?key=${encodeURIComponent(config.apiKey)}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ contents: [{ role: 'user', parts: [{ text: `Você é um assistente pedagógico do Centro Educa Mais Domingos Vieira Filho. Responda em português do Brasil. Pedido: ${prompt}` }] }], generationConfig: { temperature: 0.4, maxOutputTokens: 700 } }) }); if (!response.ok) { const detail = await response.text(); throw new Error(`Gemini ${response.status}: ${readProviderError(detail)}`) }; const data = await response.json() as { candidates?: Array<{ content?: { parts?: Array<{ text?: string }> } }> }; return data.candidates?.[0]?.content?.parts?.[0]?.text || 'O Gemini não retornou texto.'
}

function readProviderError(raw: string) { try { const parsed = JSON.parse(raw) as { error?: { message?: string } }; return parsed.error?.message || 'A API recusou a solicitação.' } catch { return 'A API recusou a solicitação.' } }

